    if bin_residual == bin_capacity {
        score += 40.0;
        // Decrease penalty if we are running out of bins or if existing bins are poor fits.
        score -= (open_bins_count as f64) * 2.0;
    }

    // 4. Mean Residual Balancing:
    // Bias towards bins that keep the overall mean residual consistent.
    // If the bin's new residual is significantly higher than the mean, it's a "loose" fit.
    if (post_residual as f64) > mean_residual {
        score += (post_residual as f64 - mean_residual) * 0.3;
