    // reward this bin heavily to keep the bin tight.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 35.0;
        } else if post_residual > next_item_size {
            // If we have space, but it's not a perfect fit, penalize based on wasted potential
            score += (post_residual - next_item_size) as f64 * 0.2;
        } else {
            // The next item cannot fit in this residual, slight penalty
            score += 5.0;
        }
    }

    // 3. Mean residual balancing: Penalize bins that deviate significantly from the average 
    // residual of all open bins to keep the pack density uniform.
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.15;

    // 4. Urgency/Pressure: If this is the only bin that can fit the current item, 
    // prioritize it to avoid creating a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // 5. Progression scaling: As we approach the end of the stream, prioritize 
    // closing bins (lower post_residual) to maximize total bin utilization.
    let progress = step_index as f64 / total_items as f64;
    score += (post_residual as f64) * progress * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Objective: Minimize score.
    // We prioritize bins that leave the smallest residual (Best Fit),
    // but penalize the creation of "dead space" that cannot fit likely upcoming items.

    let is_new_bin = bin_residual == bin_capacity;
    let progress = step_index as f64 / total_items as f64;

    // Base score: The post-placement residual (Best Fit principle).
    let mut score = post_residual as f64;

    // 1. Penalize creating a new bin unless the fitting quality is poor.
    if is_new_bin {
        // Only open a new bin if the current mean_residual is already quite small
        // or if we have very few open bins (avoiding fragmentation).
        score += 25.0 + (mean_residual * 0.5);
        if fitting_bins_count > 0 {
            score += 40.0; // Strong penalty for opening a new bin if others exist.
        }
    }

    // 2. Lookahead optimization: If a future item exists, prefer bins that accommodate it.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            // Penalty for stranding the next item: it won't fit in this bin.
            score += 15.0;
        } else {
            // Reward for keeping a bin open that can accommodate the next item.
            score -= 5.0;
        }
    }

    // 3. Fragmentation control: Penalize residuals that are too small to fit the smallest
    // likely item (10), but large enough to be wasted space.
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // 4. Global state coupling: As the process nears completion, prioritize closing bins.
    if progress > 0.8 {
        // Heavily penalize opening new bins late in the stream.
        if is_new_bin {
            score += 50.0;
        }
        // Reward filling bins to completion to reduce total bin count at end of stream.
        score -= (100.0 - post_residual as f64) * 0.1;
    }

    // 5. Fitting count adjustment: If this is the only bin that fits, prioritize it.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
