    }

    // Adaptivity: As the stream progresses, become more aggressive about 
    // consolidating items into existing bins to avoid opening new ones.
    // Penalize opening a new bin (where bin_residual == bin_capacity) as progress increases.
    if bin_residual == bin_capacity {
