    // Coupling: If the current bin is the only one that can fit the item,
    // reward it to avoid the overhead of opening a new bin prematurely.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Global balance: discourage creating bins that deviate significantly 
    // from the current average residual (encourages uniform filling).
    let diff_from_mean = (post_res - mean_residual).abs();
    score += diff_from_mean * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
