        r if r % 20 == 0 => score -= 8.0,
        r if r % 10 == 0 => score -= 4.0,
        _ => {}
    }

    // 4. New Bin Decisioning
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            score = -2000.0; // Urgent requirement
        } else {
            // Logic: Only open new if existing bins are too fragmented to be useful.
            // Increased threshold to force reuse of bins with higher mean_residual.
            let density_pressure = (open_bins_count as f64 * 3.2) + (mean_residual * 1.2);
            score += 75.0 + density_pressure;
        }
    } else {
        // Consolidation Pressure: Penalize high open_bins_count using a non-linear log curve.
        score += (open_bins_count as f64).ln().powf(1.1) * 2.5;

        // "Finish-off" bonus: Reward closing small residuals to reduce total bin count.
        if post_residual < 8 && post_residual > 0 {
            score -= 12.0;
        }

        // Anti-starvation: If a bin is nearly full but not empty, prioritize it to minimize 
        // the number of "warm" bins that are mostly empty.
        if post_residual < 15 {
            score -= 5.0 * (1.0 - (fitting_bins_count as f64 / (open_bins_count as f64 + 1.0)));
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Base score: favor Best Fit (smallest post_residual).
    let mut score = post_residual as f64;

    // 1. Dynamic Fragmentation Threshold
    // As the stream progresses, penalize "orphaned" gaps that are too small to likely fit future items.
    let progress = step_index as f64 / total_items as f64;
    let fragmentation_threshold = 15.0 + (10.0 * progress);
    if post_residual > 0 && (post_residual as f64) < fragmentation_threshold {
        score += 85.0 * (1.0 - (post_residual as f64 / fragmentation_threshold));
    }

    // 2. Lookahead Synergy
    // If next item fits, prioritize this bin. If not, penalize the bin for creating a trap.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 45.0 * (1.0 + (open_bins_count as f64 * 0.02));
        } else if post_residual > 0 {
            score += 25.0;
        }
    }

    // 3. Bin Consolidation Pressure
    // Scale penalty for opening new bins based on current bin density and mean residual.
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            score = -5000.0; // Force open new bin if no other option
        } else {
            // Only open new if existing bins are significantly under-utilized
            let density_pressure = (open_bins_count as f64 * 3.5) + (mean_residual * 1.2);
            score += 120.0 + density_pressure;
        }
    } else {
        // Reward closing bins (minimizing residual)
        score -= (bin_capacity - bin_residual) as f64 * 0.1;

        // Penalize keeping many bins open simultaneously
        score += (open_bins_count as f64).sqrt() * 5.0;
    }

    // 4. Harmonic Alignment
    // Favor residuals that align with common factors of bin capacity (assuming 100).
    if post_residual % 20 == 0 {
        score -= 12.0;
    } else if post_residual % 10 == 0 {
        score -= 6.0;
    }

    // 5. Criticality adjustment
    // If this is the only bin that can fit the item, strongly prioritize it to prevent new bin creation.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
