    if is_new_bin {
        // Only consider a new bin if we have too many open bins (high fragmentation risk)
        // or if the average residual is already quite low.
        score += (open_bins_count as f64) * 15.0;
        score += (mean_residual * 0.5);
    } else {
        // Reward utilizing existing bins to reduce open_bins_count
        score -= (open_bins_count as f64) * 2.0;
    }

    // 4. Last Chance Heuristic: If this is the only bin that fits the item,
    // reduce the penalty to ensure we don't force a new bin unnecessarily.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 40.0;
    }

    // 5. Progression Scaling: As we near the end of the stream, 
