    let alignment_bonus = if post_residual % 25 == 0 { 25.0 } 
                          else if post_residual % 20 == 0 { 18.0 } 
                          else if post_residual % 10 == 0 { 10.0 } 
                          else { 0.0 };
    score -= alignment_bonus;

    // 4. New Bin Candidate Logic:
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            score = -900.0; // Urgent: Must open a new bin if nothing else fits.
        } else {
