        score += (open_bins_count as f64).ln() * 4.5;

        // Bonus for keeping bins with larger residuals "warm" if they are currently under-utilized.
        if bin_residual as f64 > mean_residual {
            score -= 8.0;
        }

        // Final tier: Small residual completion bonus
        if post_residual < 8 && post_residual > 0 {
            score -= 12.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
