    // 1. Best-Fit Penalty: Minimize post_residual, but prioritize tight fits (Best Fit Decreasing logic)
    // We penalize larger post_residuals to encourage filling bins tightly.
    score += (post_residual as f64).powf(1.5);

    // 2. Harmonic Class Logic: Reward placements that leave remainders which are multiples of common item sizes
    // This reduces fragmentation by aligning bin residuals with expected item footprints.
    if post_residual > 0 {
        let harmonic_penalty = (post_residual % 10) as f64 * 2.5;
        score += harmonic_penalty;
    }

    // 3. Lookahead Optimization: If the next item fits into the current post_residual, incentivize this bin.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= (next_item_size as f64) * 4.0;
    }

    // 4. Thresholding: Avoid opening new bins unless necessary (fitting_bins_count == 0)
    // If the bin is new, impose a cost based on the current packing efficiency (mean_residual).
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            // Strong penalty for opening a new bin if we have existing options
            score += 250.0;
        } else {
            // Normalize new bin cost based on how much space we expect to waste
            score += mean_residual * 0.5;
        }
    }

    // 5. Progression Scaling: As the stream nears the end, prioritize closing bins over opening new ones.
    let progress = step_index as f64 / total_items as f64;
    if bin_residual == bin_capacity {
        score += (progress * 100.0);
    }

    // 6. Fragmentation control: Heavily penalize bins that are "almost" empty but too small for future items.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Base: prioritize tightest fit (Best Fit)
    let mut score = post_residual as f64;

    // 1. Refined Fragmentation Penalty: Target "Dead Zone" (1-32)
    // Expanded the range and tightened the curve to penalize "unusable" small gaps.
    if post_residual > 0 && post_residual < 33 {
        score += 94.0 - (post_residual as f64 * 0.85);
    }

    // 2. Predictive Lookahead: Enhanced penalty for blocking the next item.
    // Shifted from linear to exponential penalty for "trap" residuals.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += 85.0 + (next_item_size - post_residual) as f64 * 1.5;
        } else {
            // Reward bins that create a "perfect" match for the next item.
            let slack = post_residual - next_item_size;
            if slack < 10 {
                score -= (10 - slack) as f64 * 6.5;
            }
        }
    }

    // 3. New Bin Thresholding: Dynamic gatekeeping.
    // Increased the cost of opening a new bin by coupling with global density pressure.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items as f64;
        // Higher base penalty to force better utilization of existing bins before starting new ones.
        score = 98.0 + (open_bins_count as f64 * 0.65) + (progress * 55.0);
    }

    // 4. Residual Harmony: Target "High Utility" values (multiples of 20 and 25).
    // Prioritize residuals that leave room for two 10s or a 20.
    let rem = post_residual % 20;
    if post_residual == 0 {
        score -= 45.0; // Perfect fit is the strongest reward
    } else if rem == 0 {
        score -= 40.0;
    } else if post_residual % 25 == 0 {
        score -= 32.0;
    }

    // 5. Global Packing Pressure: Accelerate consolidation as we reach the end of the stream.
    let progress = (step_index as f64 / total_items as f64).powf(1.8);
    score -= progress * 65.0;

    // 6. Density Equilibrium: Discourage extreme fill states.
    // Tightened the "too full" penalty to avoid locking bins that could take a future medium item.
    let density_ratio = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    if density_ratio > 0.94 {
        score += 55.0; 
    } else if density_ratio < 0.25 {
        score -= 35.0; 
    }

    // 7. Entropy Control: Penalize divergence from mean_residual.
    // Reduced coefficient to allow for higher variance in early stages, tightening later.
    let deviation = (post_residual as f64 - mean_residual).abs();
    score += deviation * 0.18;

    // 8. Fitting Pressure: Reward using bins that have many siblings available.
    // Increased to force the heuristic to clear "cluttered" bins first.
    score -= (fitting_bins_count as f64) * 4.2;

    score
}

