    let is_new_bin = bin_residual == bin_capacity;

    // Base score: We prefer smaller post_residuals (Best Fit).
    // However, we penalize very small post_residuals (dead space < 10) 
    // as they prevent future large items from fitting.
    let mut score = post_residual as f64;

    if post_residual < 10 && post_residual > 0 {
        score += 25.0 * (1.0 - progress);
    }

    // Lookahead logic: If the next item is large, favor bins that can accommodate it.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 15.0 * (1.0 - progress);
        } else {
            score += 10.0 * progress;
        }
    }

    // Penalty for opening a new bin: Only do it if we are forced or if 
    // the current bin fit quality is extremely poor compared to the mean.
    if is_new_bin {
        if fitting_bins_count == 0 {
            score = 0.0; // Forced, take it.
        } else {
            // Discourage opening a new bin early unless the fit is truly necessary.
            score = 80.0 + (40.0 * progress);
        }
    } else {
        // Reward bins that keep the mean residual balanced.
        let deviation = (post_residual as f64 - mean_residual).abs();
        score += 0.5 * deviation;

        // Penalize bins that become "too full" late in the stream (fragmentation risk).
        if progress > 0.7 && post_residual < 15 {
            score += 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Base: prioritize tightest fit (Best Fit)
    let mut score = post_residual as f64;

    // 1. Refined Fragmentation Penalty: Target "Dead Zone" (1-32)
    // Expanded range and steeper penalty to prevent small, unusable slivers.
    if post_residual > 0 && post_residual < 32 {
        score += 94.0 - (post_residual as f64 * 0.65);
    }

    // 2. Predictive Lookahead: Enhanced sensitivity to the next item's impact.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            // Severe penalty for creating an unusable gap that could have fit the next item.
            score += 85.0 + (next_item_size - post_residual) as f64 * 1.5;
        } else {
            // Reward bins that leave exactly the next item's size, creating a "perfect fit" bridge.
            let slack = post_residual - next_item_size;
            if slack < 8 {
                score -= 24.0 * (1.0 - slack as f64 / 8.0);
            }
        }
    }

    // 3. New Bin Thresholding: Dynamic gatekeeping.
    // Increased the cost of opening a new bin to force better utilization of existing "poor" fits.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items as f64;
        score = 95.0 + (open_bins_count as f64 * 0.75) + (progress * 55.0);
    }

    // 4. Residual Harmony: Target "High Utility" values.
    // Multiples of 20 and 25 are critical for 100-capacity bin packing.
    let rem = post_residual % 20;
    if rem == 0 {
        score -= 42.0;
    } else if post_residual % 25 == 0 {
        score -= 35.0;
    } else if post_residual % 10 == 0 {
        score -= 12.0;
    }

    // 5. Global Packing Pressure: Accelerate consolidation as we reach the end of the stream.
    let progress = (step_index as f64 / total_items as f64).powf(1.8);
    score -= progress * 65.0;

    // 6. Density Equilibrium: Discourage extreme fill states.
    let density_ratio = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    // Strongly penalize filling a bin to >95% if it leaves a tiny, useless residual.
    if density_ratio > 0.95 {
        score += 55.0;
    } else if density_ratio < 0.35 {
        score -= 32.0;
    }

    // 7. Entropy Control: Penalize divergence from mean_residual to force uniform bin states.
    // Increased weight to minimize variance across bins.
    let deviation = (post_residual as f64 - mean_residual).abs();
    score += deviation * 0.45;

    // 8. Fitting Pressure: Reward using bins that are already "popular" (high fitting_bins_count).
    // This encourages exhausting high-fitting bins before touching others.
    score -= (fitting_bins_count as f64) * 4.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

