        score += 50.0;
    }

    // Reward for perfect fits (Best Fit principle).
    if post_residual == 0 {
        score -= 40.0;
    }

    // Heuristic: If we are near the end of the stream, prioritize closing bins over opening new ones.
    let progress = step_index as f64 / total_items as f64;
    if bin_residual == bin_capacity {
        // Penalty for opening a new bin: scales with progress to discourage new bin creation late in the stream.
        score += 25.0 + (progress * 50.0);
    }

    // Lookahead logic: if the next item fits into the current post_residual, prioritize this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 30.0;
        // Harmonic optimization: prefer leaving space for the next item if it's large.
        if next_item_size > 50 {
            score -= 10.0;
        }
    }

    // Harmonic class logic: penalize post_residuals that are awkward fractions of capacity.
    // We prefer bin_residual to be a multiple of common item sizes (e.g., 20, 25, 50).
    let rem = post_residual % 20;
    if rem == 0 {
        score -= 5.0;
    } else if rem > 15 {
        score += 10.0;
    }

    // If this is the last chance for the current item, lower the penalty for using this specific bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    score
}

