    // Penalize filling a bin to >96% if it leaves a tiny, useless residual.
    if density_ratio > 0.96 {
        score += 65.0;
    } else if density_ratio < 0.38 {
        score -= 38.0;
    }

    // 7. Entropy Control: Penalize divergence from mean_residual to force uniform bin states.
    let deviation = (post_residual as f64 - mean_residual).abs();
    score += deviation * 0.52;

    // 8. Fitting Pressure: Reward using bins that are already "popular" (high fitting_bins_count).
    // Discourage opening a new bin if an existing one is already a candidate.
    score -= (fitting_bins_count as f64) * 5.5;

