    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items as f64;
        score = 86.0 + (open_bins_count as f64 * 0.45) + (progress * 55.0);
    }

    // 4. Residual Harmony: Target "High Utility" values (multiples of 20 and 25).
    // Penalize values that leave awkward remainders (e.g., 7-12, 17-19).
    let rem = post_residual % 20;
    if rem == 0 {
        score -= 42.0;
    } else if post_residual % 25 == 0 {
        score -= 34.0;
    } else if post_residual % 10 == 9 || post_residual % 10 == 8 {
        score += 24.0;
    }

    // 5. Global Packing Pressure: Accelerate consolidation using exponential decay.
    let progress = (step_index as f64 / total_items as f64).powf(1.8);
