    // 6. Density Equilibrium: Discourage extreme fill states (too full or too sparse).
    let density_ratio = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    // Reward filling sparse bins to reduce total open bin count.
    if density_ratio < 0.35 {
        score -= 35.0 * (1.0 - density_ratio * 2.0);
    } else if density_ratio > 0.95 {
        score += 55.0; // Avoid "tight" bins that prevent future flexibility
    }

    // 7. Entropy Control: Penalize divergence from mean_residual to prevent bin variance.
