    let deviation = (post_residual as f64 - mean_residual).abs();
    score += (deviation.ln_1p()) * 18.0;

    // 8. Fitting Pressure: Reward using bins that have many siblings available.
    // This forces the algorithm to "drain" existing bins before opening new ones.
    score -= (fitting_bins_count as f64).powf(1.15) * 3.5;

