    let post_res = post_residual as f64;

    // Base score is the post_residual (Best Fit principle)
    let mut score = post_res;

    // Penalty for creating "slivers" (very small residuals) which are hard to fill later.
    // We apply a non-linear penalty for residuals in the range [1, 15].
    if post_residual > 0 && post_residual <= 15 {
        score += (16.0 - post_res).powf(1.5);
    }

    // Lookahead coupling: If the next item is large, penalize small post_residuals 
    // that would effectively orphan the current bin.
    if next_item_size > 0 {
        let lookahead_penalty = (next_item_size as f64 / post_res.max(1.0)).powf(1.2);
        score += lookahead_penalty;
    }

    // Stream progression adjustment: As we approach the end of the stream, 
    // prioritize closing existing bins (lower post_residual) over opening new ones.
    // If it's a new bin (bin_residual == bin_capacity), penalize it more as we near the end.
    if bin_residual == bin_capacity {
        score += 20.0 * (1.0 + progress.powi(2));
    }

    // Adaptive thresholding: If we have many open bins, penalize residuals that deviate 
    // significantly from the global mean_residual, promoting bin consolidation.
    if open_bins_count > 1 {
        let deviation = (post_res - mean_residual).abs();
        score += deviation * 0.5;
    }

    // Critical constraint: If this is the only bin that can fit the item, 
    // provide a strong incentive to take it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    score
}

