    let is_new_bin = bin_residual == bin_capacity;
    let mut score = post_residual as f64;

    // 1. Refined Fragmentation Penalty: Tightened for mid-range fragments to prevent "dead" space
    if post_residual > 4 && post_residual < 78 {
        score += (440.0 - (post_residual as f64 * 3.6)) * (1.2 + progress);
    }

    // 2. Predictive Lookahead: Enhanced sensitivity to the next item
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += 880.0; 
        } else {
            let slack = post_residual - next_item_size;
            score -= (280.0 - (slack as f64 * 7.2)).max(0.0);
            if slack > 0 && slack < 35 { score += 310.0; }
        }
    }

    // 3. Dynamic New-Bin Gatekeeping: Adjusted for faster consolidation
    if is_new_bin {
        score = 255.0 + (open_bins_count as f64 * 3.8) + (progress.powf(5.5) * 640.0) - (mean_residual * 4.2);
    }

    // 4. Residual Harmony & Density: Enhanced modular alignment
    if post_residual == 0 { score -= 740.0; }
    else if post_residual % 12 == 0 { score -= 190.0; }
    else if post_residual % 25 == 0 { score -= 380.0; }
    else if post_residual % 37 == 0 { score -= 290.0; }

    // 5. Global Consolidation: Aggressive late-stage closure
    score -= progress.powf(9.0) * 1100.0;

    // 6. Density Equilibrium: Optimized for high-fill state
    if fill_ratio > 0.96 {
        score += 660.0; 
    } else if fill_ratio < 0.42 {
        score -= 520.0 * (1.0 - fill_ratio).powf(5.2);
    }

    // 7. Entropy Control: Variance dampening with tighter coupling to progress
    score += (post_residual as f64 - mean_residual).abs() * (3.2 + (progress * 3.2));

    // 8. Fitting Pressure: Increased weight for bin connectivity
    score -= (fitting_bins_count as f64).min(180.0) * 145.0;

    // 9. Residual Depth Compensation: High-fill non-linear boost
    score -= (used_capacity * 1.8) + (fill_ratio.powf(12.0) * 550.0);

    // 10. Secondary Lookahead: Micro-gap "Dead Zone" penalty
    if next_item_size > 0 && post_residual > next_item_size && (post_residual - next_item_size) < 28 {
        score += 290.0;
    }

    // 11. Residual "Near-Zero" Trap: Scaling penalty based on remaining stream
    if !is_new_bin && post_residual > 0 && post_residual < 45 {
        score += 210.0 * (1.0 - progress.powf(1.8));
    }

    // 12. Cross-Bin Global Pressure: Scaling penalty for open bin count
    score += (open_bins_count as f64).powf(1.1) * 1.5;

    score
}

