    let used_capacity = (bin_capacity - bin_residual) as f64;
    let fill_ratio = used_capacity / bin_capacity as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // Initialize score based on post-fit residual with a slight preference for deeper bins
    let mut score = (post_residual as f64) * 0.85;

    // 1. Adaptive Fragmentation Penalty: Penalize mid-range fragments that are hard to fill
    if post_residual > 5 && post_residual < 65 {
        score += (380.0 - (post_residual as f64 * 3.1)) * (1.2 + progress);
    }

    // 2. Predictive Lookahead: Asymmetric penalty for tight-fit avoidance
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += 850.0; // Hard barrier for impossible fits
        } else {
            let slack = post_residual - next_item_size;
            // Reward "perfect" or "near-perfect" slack, penalize "bad" gaps
            score -= (280.0 - (slack as f64 * 7.2)).max(0.0);
            if slack > 0 && slack < 22 { score += 310.0; }
        }
    }

    // 3. Dynamic New-Bin Gatekeeping: Increased barrier to force utilization of existing bins
    if is_new_bin {
        score = 265.0 + (open_bins_count as f64 * 4.1) + (progress.powf(5.5) * 480.0) - (mean_residual * 4.2);
    }

    // 4. Harmonic Alignment: Incentivize patterns that leave multiples of common item sizes
    if post_residual == 0 { score -= 750.0; }
    else if post_residual % 20 == 0 { score -= 340.0; }
    else if post_residual % 25 == 0 { score -= 380.0; }

    // 5. Global Consolidation: Aggressive late-stage closure
    score -= progress.powf(8.5) * 950.0;

    // 6. Density Equilibrium: Fine-tuned penalty for extreme bin states
    if fill_ratio > 0.98 {
        score += 620.0; 
    } else if fill_ratio < 0.42 {
        score -= 520.0 * (1.0 - fill_ratio).powf(5.2);
    }

    // 7. Entropy Control: Penalize deviations from the mean residual
    score += (post_residual as f64 - mean_residual).abs() * (3.2 + (progress * 3.2));

    // 8. Fitting Pressure: Prefer bins that leave more options (fitting_bins_count)
    score -= (fitting_bins_count as f64).min(120.0) * 140.0;

    // 9. Residual Depth Compensation: Reward high-fill states non-linearly
    score -= (used_capacity * 1.8) + (fill_ratio.powf(12.0) * 500.0);

    // 10. Dead Zone Penalty: Penalize small, unfillable gaps
    if !is_new_bin && post_residual > 0 && post_residual < 35 {
        score += 210.0 * (1.0 - progress.powf(1.8));
    }

    // 11. Global Pressure: Scaling penalty for excessive open bins
    score += (open_bins_count as f64).powf(1.2) * 1.5;

    score
}

