    let progress = step_index as f64 / total_items as f64;

    // Penalty for creating a bin that is too small for common future items
    // If post_residual is small but not zero, it creates "dead space" that cannot fit typical items (10-80).
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // Lookahead logic: If the next item fits into the current post_residual, prioritize this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 40.0;
    }

    // If this is the only bin that can fit the item, we are forced to take it.
    // We lower the score to ensure it is picked over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New bin logic: Opening a new bin is expensive.
    // Penalize new bin opening more heavily as we progress towards the end of the stream.
    if bin_residual == bin_capacity {
        score += 25.0 + (progress * 20.0);
    }

    // Balance the global state: If the average residual across bins is high, 
    // we prefer to fill existing bins rather than spreading items thin.
    if mean_residual > 30.0 {
        score -= (mean_residual - 30.0) * 0.5;
