    // Normalize stream progression
    let progress = step_index as f64 / total_items as f64;

    // Base score is the remaining space (Best Fit objective).
    // Lower post_residual is generally better (tighter fit).
    let mut score = post_residual as f64;

    // Penalty for leaving space that is too small for common items (dead space).
    // We penalize post_residual ranges that are likely to become unusable (1..9).
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 * (1.0 + progress);
    }

    // Dynamic Lookahead coupling:
    // If the next item is large, we want to preserve bins with higher residuals.
    // We penalize tight fits if we are early in the stream.
    if next_item_size > 0 {
        let fit_margin = post_residual as f64 - next_item_size as f64;
        if fit_margin < 0.0 {
            // This bin will not fit the next item; penalize based on current bin density.
            score += (1.0 - progress) * (bin_capacity - bin_residual) as f64 * 0.5;
        }
    }

    // Heuristic for New Bin (bin_residual == bin_capacity):
    // Only open a new bin if the current open bins are "too full" or "too empty" to accommodate future items.
    if bin_residual == bin_capacity {
        // High penalty for opening a new bin early in the stream.
        // As the stream progresses, the penalty decreases to allow for better packing.
        score += 45.0 * (1.0 - progress);

        // If there are many open bins, penalize opening another one.
        score += (open_bins_count as f64).powf(1.2) * 5.0;
