    } else if fill_ratio < 0.30 {
        score -= 600.0 * (1.0 - fill_ratio).powf(6.0);
    }

    // 7. Entropy Control: Dynamic variance dampening
    score += (post_residual as f64 - mean_residual).abs() * (3.5 + (progress * 4.0));

    // 8. Fitting Pressure: Prioritize high-connectivity clusters
    score -= (fitting_bins_count as f64).min(160.0) * 150.0;

    // 9. Residual Depth Compensation: Non-linear boost for high-fill state
    score -= (used_capacity * 1.8) + (fill_ratio.powf(13.0) * 500.0);

    // 10. Secondary Lookahead: Micro-gap "Dead Zone" penalty
    if next_item_size > 0 && post_residual > next_item_size && (post_residual - next_item_size) < 32 {
        score += 350.0;
    }

    // 11. Residual "Near-Zero" Trap: Penalize small, unfillable gaps
    if !is_new_bin && post_residual > 0 && post_residual < 50 {
        score += 260.0 * (1.0 - progress.powf(2.0));
    }

    // 12. Cross-Bin Global Pressure: Scaling penalty for excessive open bins
    score -= (open_bins_count as f64 / 6.0).min(80.0) * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Objective: Minimize post_residual, but heavily penalize small fragments (1..9) 
    // and use lookahead to prefer keeping space for the next item.

    let is_new_bin = bin_residual == bin_capacity;
    let progress = step_index as f64 / total_items as f64;

    // Base score: Favor tightest fit (Best Fit)
    let mut score = post_residual as f64;

    // Penalty for creating "dead space": residues that are too small to fit common items
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Lookahead logic: If the next item fits in the current post_residual, reward this bin
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 20.0;
    }

    // Global state sensitivity: Discourage opening new bins early in the stream
    if is_new_bin {
        // If we have other bins that can fit this, penalize opening a new one heavily
        if fitting_bins_count > 0 {
            score += 50.0 + (1.0 - progress) * 30.0;
        } else {
            // If no other bin fits, this is necessary; normalize cost
            score -= 5.0;
        }
    }

    // Balance usage: If the current bin's residual is significantly better than the mean,
    // favor bins that align with the global average to keep packing density uniform
    let deviation = (post_residual as f64 - mean_residual).abs();
    score += deviation * 0.1;

    // Final scaling: favor bins that are already partially filled to pack them to completion
    if !is_new_bin && bin_residual < 30 {
        score -= 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;
    let used_capacity = (bin_capacity - bin_residual) as f64;
    let fill_ratio = used_capacity / bin_capacity as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // 1. Refined Fragmentation Penalty: Tightened for high-density packing
    if post_residual > 2 && post_residual < 82 {
        score += (440.0 - (post_residual as f64 * 3.8)) * (1.25 + progress);
    }

    // 2. Predictive Lookahead: Enhanced asymmetry for tight-fit avoidance
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += 840.0; 
        } else {
            let slack = post_residual - next_item_size;
            score -= (310.0 - (slack as f64 * 7.2)).max(0.0);
            if slack > 0 && slack < 34 { score += 310.0; }
        }
    }

    // 3. Dynamic New-Bin Gatekeeping: Adjusted for aggressive consolidation
    if is_new_bin {
        score = 265.0 + (open_bins_count as f64 * 4.4) + (progress.powf(5.5) * 610.0) - (mean_residual * 4.2);
    }

    // 4. Residual Harmony & Density: Multi-divisor alignment
    if post_residual == 0 { score -= 740.0; }
    else if post_residual % 12 == 0 { score -= 190.0; }
    else if post_residual % 20 == 0 { score -= 310.0; }
    else if post_residual % 25 == 0 { score -= 380.0; }

    // 5. Global Consolidation: Aggressive late-stage closure
    score -= progress.powf(8.8) * 920.0;

    // 6. Density Equilibrium: Penalize fragmentation at both tails
    if fill_ratio > 0.98 {
        score += 640.0; 
    } else if fill_ratio < 0.42 {
        score -= 520.0 * (1.0 - fill_ratio).powf(5.2);
    }

    // 7. Entropy Control: Dynamic variance dampening with skew correction
    score += (post_residual as f64 - mean_residual).abs() * (3.2 + (progress * 3.2));

    // 8. Fitting Pressure: Prefer bins that maximize future connectivity
    score -= (fitting_bins_count as f64).min(160.0) * 145.0;

    // 9. Residual Depth Compensation: Non-linear boost for high-fill state
    score -= (used_capacity * 1.8) + (fill_ratio.powf(12.5) * 510.0);

    // 10. Secondary Lookahead: Micro-gap "Dead Zone" penalty
    if next_item_size > 0 && post_residual > next_item_size && (post_residual - next_item_size) < 28 {
        score += 290.0;
    }

    // 11. Residual "Near-Zero" Trap: Penalize small, unfillable gaps
    if !is_new_bin && post_residual > 0 && post_residual < 45 {
        score += 210.0 * (1.0 - progress.powf(1.8));
    }

    // 12. Cross-Bin Global Pressure: Scaling penalty for excessive open bins
    score -= (open_bins_count as f64 / 6.0).min(60.0) * 3.5;

    score
}
